// ---------- Reglas fijas (mandan sobre el agente) ----------
const esPPD = d => cfg.ppd_siempre_slack !== false && String(d.metodo_pago || '').toUpperCase() === 'PPD' && !['P', 'E', 'T', 'N'].includes(d.tipo);
