    const m = String(b.fileName || '').match(/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\.xml$/i);
    if (m) xmlSat.add(m[1].toUpperCase());
