          if (!ex['Link Drive'] || soloXml) plan.adjuntar.push({ key: d.uuid, fila: ex.fila, gasto_id: ex['Gasto ID'], archivos: c.archivos, carpeta: carpeta(d.fecha), anio: anio(d.fecha), clave_binario: c.key });
