  }
  const sinSlack = estado === 'pendiente_pago' ? reglaNoSlack(d) : null;
  if (sinSlack) { motivo = `${sinSlack.motivo} · ${motivo}`; res.no_slack++; }

  let gasto = '', sugerido = '';
  if (['pendiente_pago', 'por_conciliar'].includes(estado) && !['P', 'T', 'N'].includes(d.tipo) && d.total) {
    const g = resolverGasto(d, key, destino, estado, cat, area, tipo, metodo, !sinSlack || !!sinSlack.crear_gasto);
    gasto = g.gasto; sugerido = g.sugerido; estado = g.estado;
    if (g.nota) motivo = `${motivo} · ${g.nota}`;
  }
  // PPD: aunque ya haya un gasto con el mismo monto (que normalmente significa "ya se pagó"), se avisa en Slack
  if (esPPD(d) && estado === 'pagada' && gasto && !sinSlack) {
    estado = 'pendiente_pago';
    motivo = `${motivo} · Ya hay un gasto con el mismo monto (${gasto}); se avisa porque es PPD`;
  }
  if (sinSlack && estado === 'pendiente_pago') {
    estado = sinSlack.estado || 'pagada';
    const nueva = plan.filas_nuevas.find(f => f.temp === gasto);
    if (nueva) nueva.campos.ref_banco = `n8n: ${sinSlack.motivo}`.slice(0, 120);
  }
  let enSlack = null;
  if (estado === 'pendiente_pago' && (enSlack = yaEnSlack(d))) {
    const quien = `mensaje del ${enSlack.fecha} en el canal`;
    res.ya_en_slack++;
    if (enSlack.pagada) {
      estado = 'pagada'; res.pagadas_slack++;
      motivo = `${motivo} · Ya se había pedido en Slack (${quien}) y tiene ✅`;
      const nueva = plan.filas_nuevas.find(f => f.temp === gasto);
      if (nueva) nueva.campos.ref_banco = 'n8n: pagada (✅ en Slack)';
    } else motivo = `${motivo} · Ya se había pedido en Slack (${quien}); se sigue ese mensaje`;
    bit('encontró en Slack', key, 'Slack ts', '', enSlack.ts, enSlack.pagada ? 'El mensaje tiene ✅: pagada' : 'Sin ✅ todavía');
  }
  if (c.accion === 'reclasificar') {
    res.reclasificadas++;
    const avisar = estado === 'pendiente_pago' && !enSlack && (!cfg.slack_desde || String(d.fecha || est.hoy).slice(0, 10) >= cfg.slack_desde);
    const datosLeidos = c.requiere_extraccion ? {
      'UUID': d.uuid || '', 'Tipo': d.tipo || '', 'Fecha': d.fecha ? String(d.fecha).slice(0, 10) : '', 'Serie': d.serie || '', 'Folio': d.folio || '',
      'RFC emisor': d.emisor_rfc || '', 'Emisor': d.emisor_nombre || '', 'RFC receptor': d.receptor_rfc || '', 'Subtotal': d.subtotal ?? '', 'IVA': d.iva ?? '',
      'IVA retenido': d.iva_retenido ?? '', 'ISR retenido': d.isr_retenido ?? '', 'Total': d.total ?? '', 'Moneda': d.moneda || '',
      'Método pago': d.metodo_pago || '', 'Forma pago': d.forma_pago || '', 'Conceptos': d.conceptos || '' } : {};
    plan.facturas_actualizar.push({ fila: c.fila, key, cambios: { ...datosLeidos,
      'Clasificación': clas, 'Motivo': motivo, 'Confianza': confianza ?? '', 'Destino': cfg.destinos[destino], 'Categoría': cat || '', 'Área': area || '',
      'Tipo gasto': tipo || '', 'Método sugerido': metodo, 'Estado': estado, 'Gasto ID': gasto, 'Gasto sugerido': sugerido,
      ...(avisar ? { 'Slack ts': `{{SLACK:${key}}}` } : enSlack && !enSlack.pagada ? { 'Slack ts': `'${enSlack.ts}` } : {})
    } });
    if (avisar) plan.slack.push(key);
    if (estado === 'pendiente_pago') res.pendientes_pago++;
    bit('reclasificó', key, 'Estado', 'por_validar', estado, `El agente ya respondió: ${motivo}`.slice(0, 300));
    continue;
  }
  res.facturas_nuevas++;
  if (estado === 'pendiente_pago') res.pendientes_pago++;
  if (estado === 'por_validar') res.por_validar++;
  if (estado === 'por_conciliar') res.por_conciliar++;
  if (estado === 'descartada') res.descartadas++;
  if (estado === 'complemento') res.complementos++;

  let archivos = c.archivos || [], claveBinario = c.key;
  if (!archivos.length && d.uuid && xmlSat.has(String(d.uuid).toUpperCase())) { archivos = [archivoSat(String(d.uuid).toUpperCase())]; claveBinario = 'sat'; }
  const conArchivo = archivos.length > 0;
  // slack_desde: las facturas con fecha anterior quedan pendientes de pago en la interfaz, pero sin mensaje en Slack
  const slack = estado === 'pendiente_pago' && !enSlack && (!cfg.slack_desde || String(d.fecha || est.hoy).slice(0, 10) >= cfg.slack_desde);
  plan.facturas_nuevas.push({ key, clave_binario: claveBinario, archivos, carpeta: carpeta(d.fecha), anio: anio(d.fecha), slack, valores: {
    'Clave': key, 'UUID': d.uuid || '', 'Tipo': d.tipo || '', 'Fecha': d.fecha ? String(d.fecha).slice(0, 10) : '', 'Serie': d.serie || '', 'Folio': d.folio || '',
    'RFC emisor': d.emisor_rfc || '', 'Emisor': d.emisor_nombre || '', 'RFC receptor': d.receptor_rfc || '', 'Subtotal': d.subtotal ?? '', 'IVA': d.iva ?? '',
    'IVA retenido': d.iva_retenido ?? '', 'ISR retenido': d.isr_retenido ?? '', 'Total': d.total ?? '', 'Moneda': d.moneda || '', 'Tipo de cambio': d.tipo_cambio ?? '',
    'Método pago': d.metodo_pago || '', 'Forma pago': d.forma_pago || '', 'Uso CFDI': d.uso_cfdi || '', 'Conceptos': d.conceptos || '',
    'Clasificación': clas, 'Motivo': motivo, 'Confianza': confianza ?? '', 'Destino': cfg.destinos[destino], 'Categoría': cat || '', 'Área': area || '',
    'Tipo gasto': tipo || '', 'Método sugerido': metodo, 'Estado': estado, 'Gasto ID': gasto, 'Gasto sugerido': sugerido,
    'Link Drive': conArchivo ? `{{LINK:${key}}}` : '', 'Carpeta': conArchivo ? carpeta(d.fecha) : '', 'Origen': origen, 'Buzón': c.buzon || '',
    'Remitente': c.remitente || '', 'Asunto': c.asunto || '', 'Recibida': c.recibido || '', 'Registrada': ahora, 'Corrida': est.corrida,
    'Slack ts': slack ? `{{SLACK:${key}}}` : (enSlack && !enSlack.pagada ? `'${enSlack.ts}` : ''), 'Estado SAT': d.estado_sat || ''
  } });
  bit('registró factura', key, 'Estado', '', estado, motivo);
  if (slack) plan.slack.push(key);
  if (estado === 'por_validar') plan.validacion.push({ key, emisor: d.emisor_nombre, rfc: d.emisor_rfc, total: d.total, moneda: d.moneda, fecha: d.fecha, motivo, asunto: c.asunto });
}

// ---------- Facturas ya registradas sin archivo en Drive: se sube su XML del SAT y se liga ----------
let xmlPendientes = 0;
for (const f of est.facturas) {
  const u = String(f.UUID || '').toUpperCase();
  const tieneLiga = /^https?:/i.test(String(f['Link Drive'] || ''));   // "UUID …" = la subida falló: se reintenta con el XML
  if (tieneLiga || !xmlSat.has(u) || xmlPendientes >= 150 || plan.adjuntar.some(a => a.fila === f.fila)) continue;
  const fecha = String(f.Fecha || '').slice(0, 10);
  plan.adjuntar.push({ key: f.Clave, fila: f.fila, gasto_id: f['Gasto ID'], archivos: [archivoSat(u)], carpeta: carpeta(fecha), anio: anio(fecha), clave_binario: 'sat' });
  xmlPendientes++;
  bit('adjuntó archivo', f.Clave, 'Link Drive', '', '(XML del SAT)', 'La factura llegó solo por el SAT');
}

// ---------- Facturas que una persona ya validó (cambió "Clasificación" en FACTURAS) ----------
for (const f of est.facturas) {
  if (f.Estado !== 'por_validar' || f['Gasto ID']) continue;
  const clas = String(f['Clasificación'] || '');
  if (clas === 'descartada' || clas === 'no_es_factura') {
    plan.facturas_actualizar.push({ fila: f.fila, cambios: { 'Estado': clas } });
    bit('cambió estado', f.Clave, 'Estado', 'por_validar', clas, 'Validada a mano');
    continue;
  }
  if (!['pagar', 'pagar_banregio', 'pagada_tarjeta'].includes(clas)) continue;
  const d = { uuid: f.UUID, tipo: f.Tipo, fecha: f.Fecha, serie: f.Serie, folio: f.Folio, emisor_rfc: f['RFC emisor'], emisor_nombre: f.Emisor,
    subtotal: Number(f.Subtotal) || 0, descuento: 0, iva: Number(f.IVA) || 0, iva_retenido: Number(f['IVA retenido']) || 0, isr_retenido: Number(f['ISR retenido']) || 0,
    total: Number(f.Total) || 0, moneda: f.Moneda || 'MXN', tipo_cambio: Number(f['Tipo de cambio']) || null, conceptos: f.Conceptos };
  if (!d.total || !d.fecha) continue;
  const destino = Object.keys(cfg.destinos).find(k => cfg.destinos[k] === f.Destino && k !== 'INCOME') || 'OPEX';
  const metodo = clas === 'pagar_banregio' ? 'Banregio' : (f['Método sugerido'] || '');
  const sinSlack = ESTADO[clas] === 'pendiente_pago' ? reglaNoSlack(d) : null;
  const g = resolverGasto(d, f.Clave, destino, ESTADO[clas], f['Categoría'], f['Área'], f['Tipo gasto'], metodo, !sinSlack || !!sinSlack.crear_gasto);
  if (sinSlack && g.estado === 'pendiente_pago') g.estado = sinSlack.estado || 'pagada';
  plan.facturas_actualizar.push({ fila: f.fila, key: f.Clave, cambios: { 'Estado': g.estado, 'Gasto ID': g.gasto, 'Gasto sugerido': g.sugerido,
    ...(g.estado === 'pendiente_pago' ? { 'Slack ts': `{{SLACK:${f.Clave}}}` } : {}) } });
  if (g.estado === 'pendiente_pago') plan.slack.push(f.Clave);
  bit('cambió estado', f.Clave, 'Estado', 'por_validar', g.estado, 'Validada a mano: se generó el gasto');
}

// ---------- Facturas pendientes con mensaje en Slack: revisar si ya tienen ✅ ----------
for (const f of est.facturas) {
  if (f.Estado === 'pendiente_pago' && f['Slack ts'] && !String(f['Slack ts']).startsWith('{{')) {
    plan.revisar.push({ fila: f.fila, key: f.Clave, ts: String(f['Slack ts']), registrada: String(f.Registrada || '').slice(0, 10),
      emisor: f.Emisor, total: f.Total, moneda: f.Moneda, gasto: f['Gasto ID'] });
  }
}
plan.revisar = plan.revisar.slice(0, 150);

// ---------- Movimientos bancarios (Metabase · bankMovements; cargos negativos, abonos positivos) ----------
if (cfg.bancos_activo && $('Metabase: movimientos').isExecuted) {
  const M = cfg.metabase_columnas;
  const crudos = $('Metabase: movimientos').all().map(i => i.json).filter(j => j && !j.error && j[M.monto] !== undefined && j[M.monto] !== null);
  if (!crudos.length) meta.bancos_error = 'Metabase no devolvió movimientos';
  const desde = [cfg.bancos_inicio, new Date(Date.now() - cfg.bancos_dias * 864e5).toISOString().slice(0, 10)].sort().pop();
  const ignorar = new RegExp(cfg.bancos_ignorar, 'i');
  const refs = new Set([...est.gastos, ...est.ingresos].map(o => o.ref).filter(r => r && !r.startsWith('n8n:')));
  const movs = crudos.map(j => ({ id: String(j[M.id]), fecha: String(j[M.fecha] || '').slice(0, 10), cuenta: String(j[M.cuenta] || '').trim(),
      monto: Number(j[M.monto]), moneda: String(j[M.moneda] || 'MXN'), referencia: String(j[M.referencia] || ''), descripcion: String(j[M.descripcion] || '') }))
    .filter(m => m.fecha >= desde && m.monto !== 0 && !refs.has(m.id))
    .filter(m => !(m.monto > 0 && (cfg.bancos_solo_cargos || []).some(c => norm(c) === norm(m.cuenta))))   // cobranza de clientes
    .sort((a, b) => a.fecha.localeCompare(b.fecha));
  const nuevasPorTemp = new Map(plan.facturas_nuevas.map(f => [f.valores['Gasto ID'], f]));
  // Gastos que esperan su pago: los que creó n8n (marca en "Ref banco"), los capturados a mano y los de esta corrida
  const gastos = [
    ...plan.filas_nuevas.map(g => ({ nuevo: true, id: g.temp, g, tab: g.tab, fecha: g.fecha, total: Math.abs(g.campos.total), metodo: g.campos.metodo, n8n: true, tarjeta: g.tarjeta })),
    ...est.gastos.filter(o => (!o.ref || o.ref.startsWith('n8n:')) && o.total !== null && o.fecha && o.fecha >= limite).map(o => ({
      nuevo: false, id: o.id, fila: o.fila, tab: o.tab, fecha: o.fecha, total: Math.abs(o.total), metodo: o.metodo, origen: o.origen,
      n8n: o.ref.startsWith('n8n:'), tarjeta: o.ref.startsWith('n8n:') ? /tarjeta/.test(o.ref) : esTarjeta(o.metodo) }))
  ];
  const ingresos = est.ingresos.filter(o => !o.ref && o.total !== null);
  const tomados = new Set();
  const llave = g => g.nuevo ? g.id : `${g.tab}:${g.fila}`;
  for (const m of movs) {
    if (ignorar.test(m.descripcion)) { plan.ignorados_banco.push(m); continue; }
    if (m.monto > 0) {                              // abono: ¿ya está en INCOME (capturado a mano)?
      const c = ingresos.filter(o => !tomados.has(`INCOME:${o.fila}`) && o.vintage === vintage(m.fecha) && Math.abs(Math.abs(o.total) - m.monto) <= C.tolerancia_mxn);
      if (c.length === 1) {
        tomados.add(`INCOME:${c[0].fila}`);
        plan.actualizar.push({ tab: 'INCOME', fila: c[0].fila, cambios: { origen: `${c[0].origen ? c[0].origen + ' · ' : ''}n8n mov #${m.id}` } });
        res.conciliadas_banco++;
        bit('concilió con banco', `${cfg.destinos.INCOME} fila ${c[0].fila}`, 'ORIGEN', '', `mov #${m.id}`, `${m.cuenta} · ${m.fecha} · ${m.monto}`);
      } else plan.sin_conciliar.push({ ...m, tipo: 'abono' });
      continue;
    }
    const tarjeta = esTarjeta(m.cuenta);
    const cand = gastos.filter(g => {
      if (tomados.has(llave(g)) || Math.abs(g.total - Math.abs(m.monto)) > C.tolerancia_mxn || g.tarjeta !== tarjeta) return false;
      const df = dias(m.fecha, g.fecha);
      if (g.n8n) return df >= -C.dias_despues && df <= C.dias_antes && (!g.metodo || !tarjeta || norm(g.metodo) === norm(m.cuenta));
      return Math.abs(df) <= 3 && norm(g.metodo) === norm(m.cuenta);    // capturado a mano: misma cuenta y fecha cercana
    });
    if (cand.length !== 1) { plan.sin_conciliar.push({ ...m, tipo: 'cargo', candidatos: cand.map(llave) }); continue; }
    const g = cand[0];
    tomados.add(llave(g));
    res.conciliadas_banco++;
    if (g.nuevo) {                                  // el pago ya estaba en el banco: el gasto nace pagado
      Object.assign(g.g.campos, { fecha: m.fecha, vintage: vintage(m.fecha), metodo: m.cuenta, ref_banco: m.id, origen: `n8n mov #${m.id}` });
      g.g.fecha = m.fecha;
      const f = nuevasPorTemp.get(g.id);
      if (f) {
        if (f.valores.Estado === 'pendiente_pago') res.pendientes_pago--;
        if (f.valores.Estado === 'por_conciliar') res.por_conciliar--;
        f.valores.Estado = 'pagada'; f.valores['Slack ts'] = ''; f.slack = false;
        plan.slack = plan.slack.filter(k => k !== f.key);
      }
      const u = plan.facturas_actualizar.find(x => x.cambios['Gasto ID'] === g.id);
      if (u) { u.cambios.Estado = 'pagada'; delete u.cambios['Slack ts']; plan.slack = plan.slack.filter(k => k !== u.key); }
    } else {
      const cambios = g.tab === 'FINANCIAL'
        ? { origen: `${g.origen ? g.origen + ' · ' : ''}n8n mov #${m.id}` }
        : { ref_banco: m.id, ...(g.n8n ? { fecha: m.fecha, vintage: vintage(m.fecha), metodo: m.cuenta } : {}) };
      plan.actualizar.push({ tab: g.tab, fila: g.fila, id: g.id, cambios });
      for (const f of est.facturas) {
        if (g.id && String(f['Gasto ID']) === g.id && ['pendiente_pago', 'por_conciliar'].includes(f.Estado)) {
          plan.facturas_actualizar.push({ fila: f.fila, cambios: { 'Estado': 'pagada' } });
          bit('cambió estado', f.Clave, 'Estado', f.Estado, 'pagada', `Pago encontrado en ${m.cuenta} el ${m.fecha}`);
        }
      }
    }
    bit('concilió con banco', g.id || `${g.tab} fila ${g.fila}`, 'Ref banco', '', m.id, `${m.cuenta} · ${m.fecha} · ${m.monto} · ${m.descripcion.slice(0, 60)}`);
  }
}

return [{ json: { plan, resumen: res, meta } }];

// Facturas que quedaron "por validar" porque el agente no pudo leer su PDF (sin datos: ni RFC ni total) y que no están en el SAT.
// Su PDF ya está en Drive: se baja para volver a dárselo al agente.
const cfg = $('Config').first().json;
const est = $('Estado').first().json;
const out = [];
for (const f of est.facturas) {
  if (out.length >= (cfg.max_releer_pdf || 40)) break;
  if (f.Estado !== 'por_validar' || !/^El agente no respondió/.test(String(f.Motivo || ''))) continue;
  if (f['RFC emisor'] && Number(f.Total) > 0) continue;          // ya tiene datos: se reclasifica sin el PDF
  const id = (String(f['Link Drive'] || '').match(/\/d\/([A-Za-z0-9_-]{20,})/) || [])[1];
  if (!id) continue;
  out.push({ json: { clave: String(f.Clave), fila: f.fila, file_id: id, nombre: String(f.Clave).split(':').pop() || `${id}.pdf`,
    origen: f.Origen || 'correo', buzon: f['Buzón'] || '', remitente: f.Remitente || '', asunto: f.Asunto || '', recibido: f.Recibida || '' } });
}
return out.length ? out : [{ json: { ninguno: true } }];

// Movimientos bancarios que no corresponden a ningún gasto o ingreso registrado: el agente decide en qué
// pestaña van (OPEX, FIXED_ASSETS, FINANCIAL, INCOME) o si se ignoran, en lotes de 25.
const cfg = $('Config').first().json;
const est = $('Estado').first().json;
const { plan } = $('Plan facturas').first().json;
const movs = plan.sin_conciliar.slice(0, cfg.max_movimientos_ia);
if (!movs.length) return [{ json: { sin_ia: true } }];

const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const GENERICAS = new Set(['spei', 'enviado', 'recibido', 'pago', 'pagos', 'transferencia', 'traspaso', 'cargo', 'abono', 'deposito', 'compra',
  'servicio', 'servicios', 'mexico', 'banco', 'cuenta', 'referencia', 'concepto', 'para', 'desde']);
const palabras = s => norm(s).replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length >= 4 && !GENERICAS.has(w) && !/^\d+$/.test(w)).slice(0, 3);
const todas = [...est.gastos, ...est.ingresos];
const ejemplos = m => {
  const ps = palabras(m.descripcion);
  if (!ps.length) return [];
  return todas.filter(o => ps.some(p => norm(o.descripcion + ' ' + o.proveedor).includes(p)))
    .sort((a, b) => String(b.fecha || b.vintage).localeCompare(String(a.fecha || a.vintage))).slice(0, 4)
    .map(o => ({ pestana: o.tab, descripcion: o.descripcion, categoria: o.categoria, subcategoria: o.subcategoria || undefined, area: o.area, tipo: o.tipo,
      metodo: o.metodo, total: o.total, factura: o.receipt && /^no fac/i.test(o.receipt) ? 'NO FACTURA' : undefined }));
};
const lista = vals => ({ type: 'string', enum: ['', ...(vals || []).slice(0, 150)] });   // "" = sin dato (sin uniones de tipos)
const c = est.catalogos;
const esquema = {
  type: 'object', additionalProperties: false, required: ['movimientos'],
  properties: { movimientos: { type: 'array', items: {
    type: 'object', additionalProperties: false,
    required: ['id', 'destino', 'categoria', 'subcategoria', 'area', 'tipo_gasto', 'descripcion', 'requiere_factura', 'confianza', 'motivo'],
    properties: {
      id: { type: 'string' },
      destino: { type: 'string', enum: ['OPEX', 'FIXED_ASSETS', 'FINANCIAL', 'INCOME', 'IGNORAR'] },
      categoria: lista([...new Set([...c.categorias, ...c.categorias_financial, ...c.categorias_activos])]),
      subcategoria: lista(c.subcategorias_financial), area: lista(c.areas), tipo_gasto: lista(c.tipos),
      descripcion: { type: 'string' }, requiere_factura: { type: 'boolean' }, confianza: { type: 'number' }, motivo: { type: 'string' }
    } } } }
};
const sistema = `Eres el agente de tesorería del equipo de finanzas de Atrato Technologies. Recibes movimientos bancarios
(cargos en negativo, abonos en positivo) que no corresponden a ningún gasto ni ingreso ya registrado en el budget.
Para cada uno decides:
- "destino": OPEX (gasto de operación: proveedores, nómina, impuestos, comisiones bancarias, tarjetas), FIXED_ASSETS (compra de activo fijo),
  FINANCIAL (intereses, pagos de crédito o derivados), INCOME (ingreso de tesorería: intereses ganados, rendimientos, compensaciones; solo abonos)
  o IGNORAR (traspasos entre cuentas propias de Atrato o del fideicomiso, aperturas o vencimientos de inversión, movimientos que no son ni gasto ni ingreso).
  Un abono que es devolución o reembolso de un gasto va a OPEX (se registrará en negativo).
- "categoria", "subcategoria" (solo FINANCIAL), "area" y "tipo_gasto": solo valores del catálogo; guíate por los ejemplos históricos. Si no hay forma razonable, "".
- "descripcion": texto corto en MAYÚSCULAS para el budget (por ejemplo "COMISION SPEI", "NOMINA 1A QUINCENA OCTUBRE", "INTERESES FIDARP").
- "requiere_factura": false para nómina, impuestos, comisiones bancarias, intereses y movimientos que nunca traen factura; true si el proveedor debería facturar.
- "confianza" de 0 a 1 y "motivo" en una frase.
Contexto de Atrato: los gastos de intereses casi siempre son un pago grande a Fidarp que sale del fideicomiso (alrededor de $10,000,000)
y otro que equivale al 4.9% de esos intereses (retención); ambos van a FINANCIAL.

REGLAS DEL BUDGET
${cfg.reglas}`;

const out = [];
for (let i = 0; i < movs.length; i += 25) {
  const lote = movs.slice(i, i + 25).map(m => ({ id: m.id, tipo: m.tipo, cuenta: m.cuenta, fecha: m.fecha, monto: m.monto, moneda: m.moneda,
    referencia: m.referencia, descripcion: m.descripcion, ejemplos_historicos: ejemplos(m) }));
  out.push({ json: { ids: lote.map(m => m.id), request: {
    model: cfg.ia_modelo, max_tokens: 16000,
    output_config: { effort: cfg.ia_esfuerzo, format: { type: 'json_schema', schema: esquema } },
    fallbacks: 'default',
    system: [{ type: 'text', text: sistema, cache_control: { type: 'ephemeral' } }],
    messages: [{ role: 'user', content: [{ type: 'text', text: JSON.stringify({ catalogos: c, movimientos: lote }, null, 1) }] }]
  } } });
}
return out;

// Completa el plan con los movimientos bancarios que clasificó el agente: crea su renglón en OPEX,
// FIXED_ASSETS, FINANCIAL o INCOME (o los ignora). Los nodos siguientes leen el plan de aquí.
const cfg = $('Config').first().json;
const est = $('Estado').first().json;
const base = $('Plan facturas').first().json;
const plan = JSON.parse(JSON.stringify(base.plan));
const res = Object.assign({}, base.resumen);
const meta = Object.assign({}, base.meta);
const MESES = ['ENERO', 'FEBRERO', 'MARZO', 'ABRIL', 'MAYO', 'JUNIO', 'JULIO', 'AGOSTO', 'SEPTIEMBRE', 'OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE'];
const vintage = fecha => { const m = +String(fecha).slice(5, 7); return `${String(m).padStart(2, '0')}_${MESES[m - 1]}`; };
const r2 = n => Math.round(n * 100) / 100;
const ahora = new Intl.DateTimeFormat('sv-SE', { timeZone: cfg.zona_horaria, dateStyle: 'short', timeStyle: 'short' }).format(new Date());
const bit = (accion, objeto, campo, antes, despues, comentario) => plan.bitacora.push([ahora, 'n8n', 'n8n', accion, objeto, campo || '', antes ?? '', despues ?? '', comentario || '']);
const enLista = (v, lista) => (v && lista.includes(v) ? v : '');

// Respuestas del agente por id de movimiento
const clasif = new Map();
if ($('Claude bancos').isExecuted) {
  const sol = $('Solicitudes IA bancos').all();
  $('Claude bancos').all().forEach((r, i) => {
    const j = r.json || {};
    const t = (j.content || []).find(b => b.type === 'text');
    if (j.error || j.stop_reason === 'refusal' || !t) { res.ia_errores++; return; }
    try { for (const m of (JSON.parse(t.text).movimientos || [])) clasif.set(String(m.id), m); }
    catch (e) { res.ia_errores++; }
  });
}

const fxMes = fecha => est.fx[+String(fecha).slice(5, 7)] || null;
let temp = plan.filas_nuevas.filter(f => /^NUEVO-/.test(f.temp || '')).length;
plan.movimientos_sin_clasificar = [];
for (const m of plan.sin_conciliar) {
  const k = clasif.get(m.id);
  if (!k) { plan.movimientos_sin_clasificar.push(m); continue; }       // se retoma en la siguiente corrida
  if (k.destino === 'IGNORAR' || (k.destino === 'INCOME' && m.monto < 0)) {
    plan.ignorados_banco.push({ ...m, motivo: k.motivo });
    bit('ignoró movimiento', `mov #${m.id}`, '', '', '', `${m.cuenta} · ${m.fecha} · ${m.monto} · ${k.motivo}`);
    continue;
  }
  const dudoso = k.confianza < cfg.ia_confianza_minima;               // con duda: se registra, pero sin categoría para que la complete el equipo
  const monto = r2(-m.monto);                                         // cargo (negativo) → gasto positivo; abono → negativo (reembolso)
  const usd = /usd/i.test(m.moneda) || /usd/i.test(m.cuenta);
  const tc = usd ? (fxMes(m.fecha) || 0) : 1;
  const mxn = r2(monto * tc);
  const origen = `n8n mov #${m.id} · ${m.cuenta} · ${m.descripcion.slice(0, 80)}`;
  const descripcion = (k.descripcion || m.descripcion).toUpperCase().slice(0, 80);
  let campos;
  if (k.destino === 'INCOME') {
    campos = { vintage: vintage(m.fecha), fecha: m.fecha, descripcion, amount: r2(m.monto * tc), usd: usd ? r2(m.monto) : '', vat: '', isr: '',
      total: r2(m.monto * tc), origen };
  } else if (k.destino === 'FINANCIAL') {
    campos = { vintage: vintage(m.fecha), fecha: m.fecha, categoria: dudoso ? '' : enLista(k.categoria, est.catalogos.categorias_financial),
      subcategoria: dudoso ? '' : enLista(k.subcategoria, est.catalogos.subcategorias_financial), descripcion, metodo: m.cuenta,
      amount: mxn, vat: 0, total: mxn, usd: usd ? monto : (fxMes(m.fecha) ? r2(mxn / fxMes(m.fecha)) : ''), folio: m.referencia, origen };
  } else {
    const lista = k.destino === 'FIXED_ASSETS' ? [...est.catalogos.categorias_activos, ...est.catalogos.categorias] : est.catalogos.categorias;
    campos = { id: `NUEVO-${++temp}`, vintage: vintage(m.fecha), fecha: m.fecha, categoria: dudoso ? '' : enLista(k.categoria, lista),
      area: dudoso ? '' : enLista(k.area, est.catalogos.areas), descripcion, tipo: dudoso ? '' : enLista(k.tipo_gasto, est.catalogos.tipos),
      metodo: m.cuenta, amount: mxn, vatq: false, vat: 0, vat_ret: '', isr: '', total: mxn,
      usd: usd ? monto : (fxMes(m.fecha) ? r2(mxn / fxMes(m.fecha)) : ''), user: 'NA', provider: '', folio: 'NA', invoice: '',
      receipt: k.requiere_factura ? '' : 'NO FACTURA', prorated: false, prorated_m: '', ref_banco: m.id };
  }
  plan.filas_nuevas.push({ tab: k.destino, temp: campos.id || `MOV-${m.id}`, fecha: m.fecha, desde_banco: true, campos });
  res.filas_banco++;
  bit('registró movimiento', campos.id || `mov #${m.id}`, cfg.destinos[k.destino], '', `${monto} · ${descripcion}`,
    `${dudoso ? 'Sin categoría (confianza baja). ' : ''}${k.motivo}`);
}
res.movimientos_ignorados = plan.ignorados_banco.length;
res.movimientos_pendientes = plan.movimientos_sin_clasificar.length;
return [{ json: { plan, resumen: res, meta } }];

// Modo prueba: un solo mensaje en Slack con lo que la corrida HABRÍA hecho, y el registro de la corrida.
const cfg = $('Config').first().json;
const est = $('Estado').first().json;
const { plan, resumen, meta } = $('Plan').first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const dinero = (v, m) => (v === '' || v === null || v === undefined) ? 'sin monto'
  : `${Number(v) < 0 ? '-' : ''}$${Math.abs(Number(v)).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}${m && m !== 'MXN' ? ' ' + m : ''}`;
const ESTADOS = { pendiente_pago: 'pendiente de pago', por_conciliar: 'tarjeta · por conciliar', por_validar: 'por validar', pagada: 'pagada',
  complemento: 'complemento', descartada: 'descartada' };

const lineas = plan.facturas_nuevas.slice(0, 25).map(f => {
  const v = f.valores;
  const gasto = /^NUEVO-/.test(v['Gasto ID']) ? 'crearía gasto' : v['Gasto ID'] ? `relacionaría con ${v['Gasto ID']}` : (v['Gasto sugerido'] ? `sugerencia: ${v['Gasto sugerido']}` : 'sin gasto');
  return `• *${esc(v.Emisor || 'Sin datos')}* · ${dinero(v.Total, v.Moneda)} · ${ESTADOS[v.Estado] || v.Estado} · ${gasto}` +
    `${v['Categoría'] ? ` · ${esc(v['Categoría'])}/${esc(v['Área'] || '—')}` : ''}\n   _${esc(String(v.Motivo || '').slice(0, 140))}_`;
});
const extra = plan.facturas_nuevas.length > 25 ? `\n…y ${plan.facturas_nuevas.length - 25} más` : '';
const banco = plan.filas_nuevas.filter(f => f.desde_banco);
const lineasBanco = banco.slice(0, 20).map(f => `• ${esc(f.campos.descripcion)} · ${dinero(f.campos.total)} → *${esc(cfg.destinos[f.tab])}*` +
  `${f.campos.categoria ? ` · ${esc(f.campos.categoria)}${f.campos.area ? '/' + esc(f.campos.area) : ''}` : ' · _sin categoría_'}${f.campos.receipt === 'NO FACTURA' ? ' · NO FACTURA' : ''}`);
const conciliados = plan.actualizar.filter(u => u.cambios.ref_banco || /n8n mov/.test(u.cambios.origen || '')).length;
const texto = [
  `:test_tube: *Modo prueba · corrida ${est.corrida}* (no se escribió nada). Esto habría hecho:`,
  `*${resumen.facturas_nuevas}* facturas nuevas · *${resumen.gastos_creados}* gastos creados · *${resumen.relacionadas}* relacionadas con gastos existentes · *${resumen.pendientes_pago}* pendientes de pago (mensaje a <@${cfg.slack_mencion}>) · *${resumen.por_validar}* por validar · *${resumen.por_conciliar}* de tarjeta`,
  `Duplicadas: ${resumen.duplicadas} · Anteriores al ${cfg.fecha_inicio_registro}: ${resumen.anteriores} · PDF que no eran factura: ${resumen.no_factura} · Errores de IA: ${resumen.ia_errores}` +
    ` · SAT: ${cfg.todoconta_activo ? (meta.sat_error || `${resumen.sat_filas} CFDIs revisados`) : 'apagado'}` +
    ` · Bancos: ${cfg.bancos_activo ? (meta.bancos_error || 'ver abajo') : 'apagado'}` +
    `\nSlack: canal ${resumen.slack_canal} · ${resumen.ya_en_slack} facturas ya se habían pedido ahí (${resumen.pagadas_slack} con ✅, se marcan pagadas; las demás no se vuelven a mandar) · ${resumen.no_slack} sin mensaje por regla (bancos, Shipkraken, fideicomiso, compensación)`,
  '',
  ...lineas,
  ...(extra ? [extra] : []),
  ...(cfg.bancos_activo ? ['', `*Bancos:* ${conciliados} pagos ligados a gastos existentes · ${banco.length} renglones nuevos · ${plan.ignorados_banco.length} ignorados · ${(plan.movimientos_sin_clasificar || []).length} para la siguiente corrida`, ...lineasBanco] : [])
].join('\n');
const fila = est.filas.corridas + 1;
return [{ json: {
  cuerpo: { channel: cfg.slack_canal, text: texto.slice(0, 3900), unfurl_links: false },
  valores: { valueInputOption: 'USER_ENTERED', data: [{ range: `'N8N_CORRIDAS'!A${fila}:O${fila}`, values: [[
    est.corrida, cfg.inicio_utc, new Date().toISOString(), 'ok', est.desde, 'SÍ', cfg.disparo, '', resumen.facturas_nuevas, resumen.gastos_creados,
    resumen.relacionadas, resumen.pendientes_pago, resumen.por_validar, resumen.ia_errores, 'Modo prueba: no se escribió nada'
  ]] }] }
} }];

// Revisa qué subcarpetas de mes (01_Enero…) hacen falta en Drive para las facturas de esta corrida.
const cfg = $('Config').first().json;
const { plan } = $('Plan').first().json;
const existentes = ($('Drive: carpetas del mes').first().json.files || []);
const raices = cfg.drive_raiz_por_anio;
const raizDe = anio => raices[anio] || raices[Object.keys(raices).sort().pop()];
const hay = new Set(existentes.map(f => (f.parents || []).map(p => `${p}|${f.name}`)).flat());

const necesarias = new Map();
for (const f of [...plan.facturas_nuevas, ...plan.adjuntar]) {
  if (!(f.archivos || []).length) continue;
  const raiz = raizDe(f.anio);
  const k = `${raiz}|${f.carpeta}`;
  if (!hay.has(k)) necesarias.set(k, { raiz, nombre: f.carpeta });
}
const out = [...necesarias.values()].map(c => ({ json: {
  cuerpo: { name: c.nombre, mimeType: 'application/vnd.google-apps.folder', parents: [c.raiz] }
} }));
return out.length ? out : [{ json: { ninguna: true } }];

// Un elemento por archivo a subir, con su carpeta de mes y su nombre final.
const cfg = $('Config').first().json;
const est = $('Estado').first().json;
const { plan } = $('Plan').first().json;
const raices = cfg.drive_raiz_por_anio;
const raizDe = anio => raices[anio] || raices[Object.keys(raices).sort().pop()];

const carpetas = new Map();
for (const f of ($('Drive: carpetas del mes').first().json.files || [])) for (const p of (f.parents || [])) carpetas.set(`${p}|${f.name}`, f.id);
if ($('Drive: crear carpeta').isExecuted) {
  for (const it of $('Drive: crear carpeta').all()) {
    const f = it.json || {};
    if (f.id) for (const p of (f.parents || [])) carpetas.set(`${p}|${f.name}`, f.id);
  }
}
const candidatos = new Map($('Combinar fuentes').all().map(it => [it.json.key, it]));
const xmlPorUuid = new Map();
if ($('SAT: descomprimir').isExecuted) {
  for (const it of $('SAT: descomprimir').all()) for (const b of Object.values(it.binary || {})) {
    const m = String(b.fileName || '').match(/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\.xml$/i);
    if (m) xmlPorUuid.set(m[1].toUpperCase(), b);
  }
}
const filaFactura = new Map(est.facturas.map(f => [f.fila, f]));
const limpio = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9._-]+/g, '').slice(0, 60);

const out = [];
for (const f of [...plan.facturas_nuevas.map(x => ({ ...x, datos: x.valores })), ...plan.adjuntar.map(x => ({ ...x, datos: filaFactura.get(x.fila) || {} }))]) {
  const deSat = f.clave_binario === 'sat';
  const cand = deSat ? null : candidatos.get(f.clave_binario || f.key);
  if (!deSat && (!cand || !cand.binary)) continue;
  const folderId = carpetas.get(`${raizDe(f.anio)}|${f.carpeta}`);
  if (!folderId) continue;
  const d = f.datos;
  for (const a of (f.archivos || [])) {
    const bin = deSat ? xmlPorUuid.get(a.uuid) : cand.binary[a.binary_key];
    if (!bin) continue;
    const uuid8 = String(d.UUID || '').slice(0, 8);
    const nombre = cfg.renombrar_archivos && (d['RFC emisor'] || uuid8)
      ? `${limpio(d['RFC emisor']) || 'SINRFC'}_${limpio(`${d.Serie || ''}${d.Folio || ''}`) || 'SF'}_${uuid8 || limpio(d.Fecha)}.${a.ext}`
      : a.nombre;
    out.push({ json: { key: f.key, ext: a.ext, nombre_drive: nombre, folder_id: folderId, carpeta: f.carpeta, binary_key: a.binary_key },
      binary: { [a.binary_key]: bin } });
  }
}
return out.length ? out : [{ json: { ninguno: true } }];

// Archivos que Drive rechazó en el primer intento (casi siempre por subir muchos seguidos: 403 por límite de velocidad).
// Se vuelven a mandar después de una pausa.
const entrada = $('Archivos a subir').all();
const out = [];
$('Drive: subir').all().forEach((r, i) => {
  const a = entrada[i];
  if (!a || !a.json || a.json.ninguno || (r.json && r.json.id)) return;
  out.push({ json: a.json, binary: a.binary });
});
return out.length ? out : [{ json: { ninguno: true } }];

// Justo antes de escribir se vuelven a leer las pestañas (por si alguien capturó mientras corría el flujo):
// se asigna el ID definitivo (26-####) a cada gasto nuevo de OPEX y FIXED_ASSETS y el renglón donde va cada fila nueva.
const cfg = $('Config').first().json;
const est = $('Estado').first().json;
const { plan } = $('Plan').first().json;
const rangos = $('Sheets: releer').first().json.valueRanges || [];
const TABS = ['OPEX', 'FIXED_ASSETS', 'FINANCIAL', 'INCOME'];
const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();

const fresco = {};
const max = Object.assign({}, est.max_codigo);
TABS.forEach((t, i) => {
  const p = est.pestanas[t];
  const vals = (rangos[i] && rangos[i].values) || [];
  if (!p || p.error) { fresco[t] = null; return; }
  const h = vals.findIndex((r, j) => j < 25 && norm(r && r[0]) === 'vintage');
  const col = p.col;
  const claves = ['fecha', 'descripcion', 'amount', 'total'].map(k => col[k]).filter(x => x >= 0);
  let ultima = h + 1;
  const filaPorId = {};
  for (let j = h + 1; j < vals.length; j++) {
    const r = vals[j] || [];
    if (claves.some(c => r[c] !== '' && r[c] !== undefined && r[c] !== null)) ultima = j + 1;
    const id = col.id >= 0 ? String(r[col.id] ?? '').trim() : '';
    if (id) {
      filaPorId[id] = j + 1;
      const m = id.match(/^(\d{2})-(\d+)$/);
      if (m) max[m[1]] = Math.max(max[m[1]] || 0, +m[2]);
    }
  }
  const ult = vals[ultima - 1] || [];
  const nCols = Math.max((vals[h] || []).length, ...Object.values(col).map(x => x + 1));
  fresco[t] = { ultima, fila_por_id: filaPorId, nCols, formulas: Array.from({ length: nCols }, (_, k) => typeof ult[k] === 'string' && ult[k].startsWith('=')) };
});

const nuevas = plan.filas_nuevas.slice().sort((a, b) => String(a.fecha).localeCompare(String(b.fecha)));
const siguiente = Object.fromEntries(TABS.map(t => [t, fresco[t] ? fresco[t].ultima + 1 : null]));
const filas = {}, codigos = {};
for (const f of nuevas) {
  if (!fresco[f.tab]) continue;
  filas[f.temp] = siguiente[f.tab]++;
  if (['OPEX', 'FIXED_ASSETS'].includes(f.tab) && est.pestanas[f.tab].col.id >= 0) {
    const pre = String(f.fecha).slice(2, 4);
    max[pre] = (max[pre] || 0) + 1;
    codigos[f.temp] = `${pre}-${max[pre]}`;
  } else {
    codigos[f.temp] = `${cfg.destinos[f.tab]} fila ${filas[f.temp]}`;
  }
}
return [{ json: { codigos, filas, fresco } }];

// Un mensaje en Slack por cada factura nueva pendiente de pago, etiquetando al responsable.
const cfg = $('Config').first().json;
const est = $('Estado').first().json;
const { plan } = $('Plan').first().json;
const { codigos } = $('Asignar IDs').first().json;

const enlaces = {};
for (const [subida, entrada] of [['Drive: subir', 'Archivos a subir'], ['Drive: subir (reintento)', 'Subidas fallidas']]) {
  if (!$(subida).isExecuted) continue;
  const subidos = $(entrada).all();
  $(subida).all().forEach((r, i) => {
    const a = subidos[i] && subidos[i].json;
    if (!a || !r.json || !r.json.id) return;
    if (!enlaces[a.key] || a.ext === 'pdf') enlaces[a.key] = `https://drive.google.com/file/d/${r.json.id}/view`;
  });
}
const previas = Object.fromEntries(est.facturas.map(f => [String(f.Clave), f]));
const nuevas = Object.fromEntries(plan.facturas_nuevas.map(f => [f.key, f.valores]));
const gastoDe = k => {
  const n = nuevas[k] && nuevas[k]['Gasto ID'];
  if (n) return codigos[n] || n;
  const u = plan.facturas_actualizar.find(x => x.key === k);
  return u ? (codigos[u.cambios['Gasto ID']] || u.cambios['Gasto ID'] || '') : '';
};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const dinero = (v, m) => (v === '' || v === null || v === undefined) ? 'sin monto'
  : `$${Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}${m && m !== 'MXN' ? ' ' + m : ''}`;
const dmy = s => (s ? `${String(s).slice(8, 10)}/${String(s).slice(5, 7)}/${String(s).slice(2, 4)}` : 's/f');

const out = [];
for (const k of plan.slack) {
  const u = plan.facturas_actualizar.find(x => x.key === k);
  const f = nuevas[k] || (previas[k] && Object.assign({}, previas[k], u ? u.cambios : {}));
  if (!f) continue;
  const link = enlaces[k] || (previas[k] && previas[k]['Link Drive']) || '';
  const gasto = gastoDe(k);
  const lineas = [
    `<@${cfg.slack_mencion}> *Factura pendiente de pago*`,
    `*${esc(f.Emisor || 'Emisor sin datos')}*${f['RFC emisor'] ? ` (${esc(f['RFC emisor'])})` : ''}`,
    `*Total:* ${dinero(f.Total, f.Moneda)} · *Fecha:* ${dmy(f.Fecha)} · *Folio:* ${esc(`${f.Serie || ''}${f.Folio || ''}` || 's/f')}`,
    `*Pagar por:* ${esc(f['Método sugerido'] || 'por definir')} · *Método SAT:* ${esc(f['Método pago'] || '—')}`,
    `*Gasto:* ${esc(gasto || 'sin gasto')} · ${esc(f['Categoría'] || 'sin categoría')} / ${esc(f['Área'] || 'sin área')}`,
    link ? `<${link}|Ver factura>` : '_Sin archivo: solo viene del SAT_'
  ];
  out.push({ json: { key: k, cuerpo: {
    channel: cfg.slack_canal, unfurl_links: false, unfurl_media: false,
    text: `Factura pendiente de pago: ${f.Emisor || ''} · ${dinero(f.Total, f.Moneda)}`,
    blocks: [
      { type: 'section', text: { type: 'mrkdwn', text: lineas.join('\n') } },
      { type: 'context', elements: [{ type: 'mrkdwn', text: 'Cuando esté pagada, reacciona con :white_check_mark: a este mensaje.' }] }
    ]
  } } });
}
return out.length ? out : [{ json: { ninguno: true } }];

// Facturas pendientes que ya tienen mensaje en Slack: se revisa si alguien les puso ✅.
const { plan } = $('Plan').first().json;
const out = plan.revisar.map(r => ({ json: r }));
return out.length ? out : [{ json: { ninguno: true } }];

// ✅ en el mensaje = pagada. Sin ✅: recordatorio en el hilo a los N días de pedida y luego cada N días
// (slack_recordatorio_dias), etiquetando a quienes pagan. Va en la primera corrida después de cada marca de N días,
// así un fin de semana o festivo no se salta el recordatorio ni lo repite.
const cfg = $('Config').first().json;
const est = $('Estado').first().json;
const pagadaSi = new Set(cfg.slack_reacciones_pagada);
const DIA = 864e5, cada = (cfg.slack_recordatorio_dias || 7) * DIA;
const menciones = (cfg.slack_recordatorio_menciones || [cfg.slack_mencion]).map(u => `<@${u}>`).join(' ');
const ahora = Date.now(), anterior = new Date(est.desde).getTime() || (ahora - DIA);
const pagadas = [];
const out = [];
if ($('Slack: reacciones').isExecuted) {
  const revisar = $('Revisar ✅').all();
  $('Slack: reacciones').all().forEach((r, i) => {
    const f = revisar[i] && revisar[i].json;
    if (!f || f.ninguno) return;
    const j = r.json || {};
    if (!j.ok) return;                                        // sin permiso o mensaje borrado: se deja igual
    const reacciones = ((j.message || {}).reactions || []).map(x => String(x.name).split('::')[0]);
    if (reacciones.some(n => pagadaSi.has(n))) { pagadas.push(f); return; }
    // Desde cuándo se pidió: la hora del mensaje de Slack (el ts es un epoch en segundos)
    const pedida = Number(String(f.ts).split('.')[0]) * 1000 || new Date(f.registrada || est.hoy).getTime();
    const semanas = t => Math.floor((t - pedida) / cada);
    if (semanas(ahora) < 1 || semanas(ahora) <= semanas(anterior)) return;
    const dias = Math.floor((ahora - pedida) / DIA);
    const monto = f.total !== '' && f.total != null
      ? `$${Number(f.total).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}${f.moneda && f.moneda !== 'MXN' ? ' ' + f.moneda : ''}` : '';
    out.push({ json: { key: f.key, cuerpo: { channel: cfg.slack_canal, thread_ts: f.ts,
      text: `${menciones} Recordatorio de pago: esta factura lleva ${dias} días sin :white_check_mark:.` +
        `${f.emisor ? ` *${f.emisor}*` : ''}${monto ? ` · ${monto}` : ''}${f.gasto ? ` · gasto ${f.gasto}` : ''}. Si ya se pagó, pónganle :white_check_mark: al mensaje.` } } });
  });
}
if (!out.length) return [{ json: { ninguno: true, pagadas } }];
out[0].json.pagadas = pagadas;
return out;

// Arma TODO lo que se escribe en el Budget en una sola operación: renglones nuevos en OPEX, FIXED_ASSETS,
// FINANCIAL e INCOME (con el formato del renglón anterior), cambios en renglones existentes, FACTURAS,
// BITACORA y el registro de la corrida. OPEX-CONTA no se toca.
const cfg = $('Config').first().json;
const est = $('Estado').first().json;
const { plan, resumen, meta } = $('Plan').first().json;
const asig = $('Asignar IDs').first().json;
const T = s => `'${s}'`;
const letra = i => { let s = '', n = i + 1; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };
const ahoraIso = new Date().toISOString();
const seguro = v => (typeof v === 'string' && (/^[=+@]/.test(v) || /^-[^\d]/.test(v)) ? `'${v}` : v);    // un texto de correo no se vuelve fórmula
// En el Budget la fecha es texto dd/mm/aa (columna con formato texto); el apóstrofo evita que Sheets la convierta en número
const fechaTexto = iso => `'${String(iso).slice(8, 10)}/${String(iso).slice(5, 7)}/${String(iso).slice(2, 4)}`;
const comoTexto = v => (typeof v === 'string' && v && !v.startsWith("'") ? `'${v}` : v);

// ---------- Enlaces de Drive, ts de Slack y códigos ----------
const enlaces = {};
let erroresDrive = 0;
// Primer intento y reintento (los que Drive rechazó por límite de velocidad se mandan otra vez tras una pausa)
for (const [subida, entrada, reintento] of [['Drive: subir', 'Archivos a subir', false], ['Drive: subir (reintento)', 'Subidas fallidas', true]]) {
  if (!$(subida).isExecuted) continue;
  const subidos = $(entrada).all();
  $(subida).all().forEach((r, i) => {
    const a = subidos[i] && subidos[i].json;
    if (!a || a.ninguno) return;
    if (!r.json || !r.json.id) { if (reintento || !$('Drive: subir (reintento)').isExecuted) erroresDrive++; return; }
    if (!enlaces[a.key] || a.ext === 'pdf') enlaces[a.key] = `https://drive.google.com/file/d/${r.json.id}/view`;
  });
}
for (const f of est.facturas) if (f['Link Drive'] && !enlaces[f.Clave]) enlaces[f.Clave] = f['Link Drive'];
const tsSlack = {};
let erroresSlack = 0;
if ($('Slack: publicar factura').isExecuted) {
  const msgs = $('Mensajes Slack').all();
  $('Slack: publicar factura').all().forEach((r, i) => {
    const m = msgs[i] && msgs[i].json;
    if (!m || m.ninguno) return;
    if (r.json && r.json.ok && r.json.ts) tsSlack[m.key] = r.json.ts; else erroresSlack++;
  });
}
const resolver = v => {
  if (typeof v !== 'string') return v;
  return v.replace(/\{\{LINK:([^}]+)\}\}/g, (_, k) => enlaces[k] || (/^[0-9A-F-]{36}$/.test(k) ? `UUID ${k}` : ''))
    .replace(/\{\{SLACK:([^}]+)\}\}/g, (_, k) => (tsSlack[k] ? `'${tsSlack[k]}` : ''))
    .replace(/NUEVO-\d+/g, t => asig.codigos[t] || t);
};
const data = [], dataControl = [];
const CONTROL = /^'(FACTURAS|BITACORA|N8N_CORRIDAS|N8N_SAT)'!/;     // pestañas que viven en la hoja de control
const poner = (rango, fila) => (CONTROL.test(rango) ? dataControl : data).push({ range: rango, values: [fila.map(v => (v === null ? null : seguro(resolver(v))))] });

// ---------- Renglones nuevos en las pestañas de registro ----------
const hojas = (($('Sheets: pestañas').first().json || {}).sheets || []).map(s => s.properties);
const requests = [];
const nuevasPorTab = {};
for (const f of plan.filas_nuevas) {
  const fila = asig.filas[f.temp];
  if (!fila) continue;
  (nuevasPorTab[f.tab] = nuevasPorTab[f.tab] || []).push({ ...f, fila });
}
for (const [tab, filas] of Object.entries(nuevasPorTab)) {
  const p = est.pestanas[tab], fr = asig.fresco[tab];
  const nCols = fr.nCols;
  for (const f of filas) {
    const valoresFila = Array(nCols).fill('');
    for (const [k, v] of Object.entries(f.campos)) {
      const j = p.col[k];
      if (j === undefined || j < 0 || j >= nCols) continue;
      valoresFila[j] = k === 'fecha' ? fechaTexto(v) : k === 'id' ? comoTexto(resolver(v)) : v;
    }
    for (let j = 0; j < nCols; j++) if (fr.formulas[j]) valoresFila[j] = null;     // se queda la fórmula copiada
    poner(`${T(p.nombre)}!A${f.fila}:${letra(nCols - 1)}${f.fila}`, valoresFila);
  }
  // Formato, listas desplegables, casillas y fórmulas: se copian del último renglón capturado
  const hoja = hojas.find(h => h.title === p.nombre) || {};
  if (hoja.sheetId === undefined) continue;
  const grid = hoja.gridProperties || {};
  const ultimaNueva = Math.max(...filas.map(f => f.fila));
  if (grid.rowCount && ultimaNueva > grid.rowCount) requests.push({ appendDimension: { sheetId: hoja.sheetId, dimension: 'ROWS', length: ultimaNueva - grid.rowCount } });
  if (grid.columnCount && nCols > grid.columnCount) requests.push({ appendDimension: { sheetId: hoja.sheetId, dimension: 'COLUMNS', length: nCols - grid.columnCount } });
  const copia = tipo => ({ copyPaste: {
    source: { sheetId: hoja.sheetId, startRowIndex: fr.ultima - 1, endRowIndex: fr.ultima, startColumnIndex: 0, endColumnIndex: nCols },
    destination: { sheetId: hoja.sheetId, startRowIndex: fr.ultima, endRowIndex: ultimaNueva, startColumnIndex: 0, endColumnIndex: nCols },
    pasteType: tipo, pasteOrientation: 'NORMAL' } });
  requests.push(copia('PASTE_FORMAT'), copia('PASTE_DATA_VALIDATION'));
  if (fr.formulas.some(Boolean)) requests.push(copia('PASTE_FORMULA'));
}

// ---------- Cambios en renglones existentes ----------
let noEncontrados = 0;
const usaRef = new Set();
for (const u of plan.actualizar) {
  const p = est.pestanas[u.tab], fr = asig.fresco[u.tab];
  if (!p || !fr) { noEncontrados++; continue; }
  const fila = u.id ? fr.fila_por_id[u.id] : u.fila;          // con ID se ubica de nuevo por si el renglón se movió
  if (!fila) { noEncontrados++; continue; }
  for (const [k, v] of Object.entries(u.cambios)) {
    const L = p.letras[k];
    if (!L) continue;
    if (k === 'ref_banco') usaRef.add(u.tab);
    poner(`${T(p.nombre)}!${L}${fila}`, [k === 'fecha' ? fechaTexto(v) : v]);
  }
}
// Renglones que n8n escribió antes con la fecha como número (se veía 46296): se pasan a texto dd/mm/aa
for (const o of est.gastos) {
  const p = est.pestanas[o.tab];
  if (!o.fecha_num || !o.fecha || !String(o.ref).startsWith('n8n') || !p || !p.letras.fecha) continue;
  poner(`${T(p.nombre)}!${p.letras.fecha}${o.fila}`, [fechaTexto(o.fecha)]);
}
// Columna "Ref banco (n8n)" (W) en OPEX y FIXED_ASSETS: se crea el encabezado la primera vez
for (const tab of ['OPEX', 'FIXED_ASSETS']) {
  const p = est.pestanas[tab];
  if (!p || !p.crear_ref || !(usaRef.has(tab) || (nuevasPorTab[tab] || []).length)) continue;
  poner(`${T(p.nombre)}!${p.letras.ref_banco}${p.fila_encabezado}`, [cfg.columna_ref_banco]);
  const hoja = hojas.find(h => h.title === p.nombre) || {};
  const g = hoja.gridProperties || {};
  if (g.columnCount && g.columnCount < p.col.ref_banco + 1 && !(nuevasPorTab[tab] || []).length) {
    requests.push({ appendDimension: { sheetId: hoja.sheetId, dimension: 'COLUMNS', length: p.col.ref_banco + 1 - g.columnCount } });
  }
}
// El gasto de una factura que acaba de recibir su archivo también recibe el enlace
for (const a of plan.adjuntar) {
  if (!a.gasto_id || !enlaces[a.key]) continue;
  for (const tab of ['OPEX', 'FIXED_ASSETS']) {
    const fila = asig.fresco[tab] && asig.fresco[tab].fila_por_id[a.gasto_id];
    if (fila && est.pestanas[tab].letras.invoice) poner(`${T(est.pestanas[tab].nombre)}!${est.pestanas[tab].letras.invoice}${fila}`, [enlaces[a.key]]);
  }
}

// ---------- FACTURAS ----------
const enc = est.encabezado_facturas;
const letraFac = h => { const i = enc.indexOf(h); return i >= 0 ? letra(i) : null; };
let filaFac = est.filas.facturas + 1;
for (const f of plan.facturas_nuevas) {
  poner(`'FACTURAS'!A${filaFac}:${letra(enc.length - 1)}${filaFac}`,
    enc.map(h => (['Clave', 'Gasto ID'].includes(h) ? comoTexto(resolver(f.valores[h] ?? '')) : (f.valores[h] ?? ''))));
  filaFac++;
}
const pagadas = (($('Recordatorios').first() || {}).json || {}).pagadas || [];
const cambiosFac = [
  ...plan.facturas_actualizar,
  ...plan.adjuntar.map(a => ({ fila: a.fila, cambios: { 'Link Drive': `{{LINK:${a.key}}}`, 'Carpeta': a.carpeta } })),
  ...pagadas.map(p => ({ fila: p.fila, cambios: { 'Estado': 'pagada' } }))
];
for (const u of cambiosFac) {
  for (const [h, v] of Object.entries(u.cambios)) {
    const L = letraFac(h);
    if (L) poner(`'FACTURAS'!${L}${u.fila}`, [h === 'Gasto ID' ? comoTexto(resolver(v)) : v]);
  }
}

// ---------- BITACORA ----------
const ahora = new Intl.DateTimeFormat('sv-SE', { timeZone: cfg.zona_horaria, dateStyle: 'short', timeStyle: 'short' }).format(new Date());
const bitacora = plan.bitacora.slice();
for (const p of pagadas) bitacora.push([ahora, 'n8n', 'n8n', 'cambió estado', p.key, 'Estado', 'pendiente_pago', 'pagada', 'Tiene ✅ en Slack']);
let filaBit = est.filas.bitacora + 1;
for (const b of bitacora) { poner(`'BITACORA'!A${filaBit}:I${filaBit}`, b); filaBit++; }

// ---------- Registro de la corrida y del SAT ----------
const notas = [
  meta.sat_error ? `SAT: ${meta.sat_error}` : (cfg.todoconta_activo ? `SAT: ${resumen.sat_filas} CFDIs revisados` : 'SAT apagado'),
  resumen.reclasificadas ? `${resumen.reclasificadas} facturas reclasificadas (el agente no había respondido)` : '',
  `Slack: canal ${resumen.slack_canal}, ${resumen.ya_en_slack || 0} ya pedidas ahí (${resumen.pagadas_slack || 0} con ✅)`,
  cfg.bancos_activo ? (meta.bancos_error ? `Bancos: ${meta.bancos_error}` : `Bancos: ${resumen.conciliadas_banco} conciliados, ${resumen.filas_banco} registrados, ${resumen.movimientos_ignorados || 0} ignorados, ${resumen.movimientos_pendientes || 0} para la siguiente corrida`) : 'Bancos apagado',
  plan.ignoradas.length ? `${plan.ignoradas.length} PDF no eran factura` : '',
  noEncontrados ? `${noEncontrados} renglones no encontrados al escribir` : '',
  pagadas.length ? `${pagadas.length} marcadas pagadas por ✅` : '',
  ...(est.errores || [])
].filter(Boolean).join(' · ');
const correos = $('Gmail: facturas').all().filter(i => i.json && i.json.id).length;
const errores = resumen.ia_errores + erroresDrive + erroresSlack;
poner(`'N8N_CORRIDAS'!A${est.filas.corridas + 1}:O${est.filas.corridas + 1}`, [
  est.corrida, cfg.inicio_utc, ahoraIso, 'ok', est.desde, 'NO', cfg.disparo, correos, resumen.facturas_nuevas, resumen.gastos_creados + resumen.filas_banco,
  resumen.relacionadas, resumen.pendientes_pago, resumen.por_validar, errores, notas
]);
if (cfg.todoconta_activo && $('SAT: leer respuestas').isExecuted) {
  const s = $('SAT: leer respuestas').first().json;
  let filaSat = est.filas.sat + 1;
  for (const [paso, x] of Object.entries(s.respuestas || {})) {
    poner(`'N8N_SAT'!A${filaSat}:E${filaSat}`, [ahora, paso, (s.ventana || {}).csv ? s.ventana.csv[0] : '', est.hoy, String((x || {}).texto || '').slice(0, 450)]);
    filaSat++;
  }
}

// ---------- Candado: en el Budget n8n solo agrega renglones ----------
// Nunca borra renglones, columnas ni pestañas, y nunca vacía ni reemplaza lo que capturó una persona.
// En renglones existentes solo llena celdas vacías (Invoice, Folio, Ref banco…) o agrega texto al final (ORIGEN);
// los renglones que creó n8n (marca "n8n" en Ref banco u ORIGEN) sí los puede completar.
const TIPOS_OK = new Set(['appendDimension', 'copyPaste']);
const primeraNueva = {};                                    // sheetId → índice (base 0) del primer renglón nuevo
for (const tab of Object.keys(nuevasPorTab)) {
  const hoja = hojas.find(h => h.title === est.pestanas[tab].nombre);
  if (hoja) primeraNueva[hoja.sheetId] = asig.fresco[tab].ultima;
}
for (const r of requests) {
  const tipo = Object.keys(r)[0];
  if (!TIPOS_OK.has(tipo)) throw new Error(`Candado del Budget: operación no permitida (${tipo}). No se escribió nada.`);
  if (tipo === 'copyPaste') {
    const dst = r.copyPaste.destination;
    if (!(dst.startRowIndex >= primeraNueva[dst.sheetId])) throw new Error('Candado del Budget: se intentó copiar formato sobre renglones existentes. No se escribió nada.');
  }
}
const actuales = {};                                        // nombre de pestaña → valores actuales (releídos con fórmulas)
['OPEX', 'FIXED_ASSETS', 'FINANCIAL', 'INCOME'].forEach((t, i) => {
  const p = est.pestanas[t];
  if (p) actuales[p.nombre] = (($('Sheets: releer').first().json.valueRanges || [])[i] || {}).values || [];
});
const tabPorNombre = Object.fromEntries(Object.entries(est.pestanas).map(([t, p]) => [p.nombre, t]));
const colIndex = L => [...L].reduce((n, ch) => n * 26 + ch.charCodeAt(0) - 64, 0) - 1;
const vacio = v => v === '' || v === null || v === undefined || /^na$/i.test(String(v).trim());
const bloqueados = [];
for (const w of data) {
  const m = w.range.match(/^'(.+)'!([A-Z]+)(\d+)/);
  if (!m) continue;
  const [, hojaNombre, L, filaTxt] = m;
  const tab = tabPorNombre[hojaNombre], fila = +filaTxt;
  if (!tab || !asig.fresco[tab]) continue;
  if (fila > asig.fresco[tab].ultima) continue;              // renglón nuevo: permitido
  const p = est.pestanas[tab], cur = actuales[hojaNombre][fila - 1] || [];
  const marca = String((p.col.ref_banco >= 0 ? cur[p.col.ref_banco] : '') || (p.col.origen >= 0 ? cur[p.col.origen] : '') || '');
  const deN8n = /n8n/i.test(marca);
  const esEncabezado = fila === p.fila_encabezado;
  w.values[0] = w.values[0].map((v, k) => {
    if (v === null) return null;                             // null = no tocar la celda
    const col = colIndex(L) + k, antes = cur[col];
    const nuevoVacio = vacio(v) && !/^na$/i.test(String(v).trim());
    let ok;
    if (nuevoVacio) ok = vacio(antes);                       // nunca vaciar una celda con datos
    else if (deN8n || vacio(antes) || String(v) === String(antes)) ok = true;
    else if (esEncabezado) ok = vacio(antes);
    else ok = typeof v === 'string' && String(v).startsWith(String(antes));   // solo agregar texto al final (ORIGEN)
    if (!ok) bloqueados.push(`${hojaNombre}!${letra(col)}${fila}`);
    return ok ? v : null;
  });
}

return [{ json: {
  hay_copiar: requests.length > 0,
  copiar: { requests },
  hay_budget: data.length > 0,
  valores: { valueInputOption: 'USER_ENTERED', data },
  valoresControl: { valueInputOption: 'USER_ENTERED', data: dataControl },
  totales: { escrituras: data.length + dataControl.length, filas_nuevas: Object.fromEntries(Object.entries(nuevasPorTab).map(([t, f]) => [t, f.length])),
    codigos: Object.values(asig.codigos), erroresDrive, erroresSlack, bloqueados }
} }];

// Correo a facturacion@ con los gastos nuevos que ninguna regla resolvió (regla 5).
const cfg = $('Config').first().json;
const est = $('Estado').first().json;
const { plan } = $('Plan').first().json;
if (!plan.validacion.length) return [{ json: { ninguno: true } }];
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const dinero = (v, m) => (v === null || v === undefined || v === '') ? 'sin monto'
  : `$${Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}${m && m !== 'MXN' ? ' ' + m : ''}`;
const filas = plan.validacion.map(v => `<tr>
  <td style="padding:6px 10px;border-bottom:1px solid #E6E2F0">${esc(v.emisor || 'Sin datos')}<br><span style="color:#667085;font-size:12px">${esc(v.rfc || '')}</span></td>
  <td style="padding:6px 10px;border-bottom:1px solid #E6E2F0;text-align:right;white-space:nowrap">${dinero(v.total, v.moneda)}</td>
  <td style="padding:6px 10px;border-bottom:1px solid #E6E2F0;white-space:nowrap">${esc(String(v.fecha || '').slice(0, 10))}</td>
  <td style="padding:6px 10px;border-bottom:1px solid #E6E2F0;color:#475467">${esc(v.motivo)}</td></tr>`).join('');
const html = `<div style="font-family:Arial,sans-serif;color:#333;font-size:14px">
<p>Hola,</p>
<p>Estas facturas llegaron hoy y ninguna regla las resuelve. ¿Hay que registrarlas y pagarlas?</p>
<table style="border-collapse:collapse;font-size:13px">
<tr style="background:#4D4590;color:#fff"><th style="padding:6px 10px;text-align:left">Emisor</th><th style="padding:6px 10px;text-align:right">Total</th><th style="padding:6px 10px;text-align:left">Fecha</th><th style="padding:6px 10px;text-align:left">Por qué está aquí</th></tr>
${filas}</table>
<p>Para resolverlas, en la pestaña <b>FACTURAS</b> del Budget cambia la columna <b>Clasificación</b> a <i>pagar</i>, <i>pagar_banregio</i>, <i>pagada_tarjeta</i> o <i>descartada</i>. En la siguiente corrida se genera el gasto y, si hay que pagarla, el aviso en Slack.</p>
<p style="color:#667085;font-size:12px">Mensaje automático del flujo de gastos (n8n) · corrida ${est.corrida}</p></div>`;
return [{ json: { para: cfg.correo_validacion_para, asunto: `Validar ${plan.validacion.length} gasto(s) nuevo(s) · ${est.hoy}`, html } }];

// Datos para la interfaz (artefacto "Gastos Atrato"): renglones del Budget desde interfaz_desde_mes, más las
// facturas, la bitácora y las corridas de la hoja de control, tal como están en las hojas (encabezado + filas).
// La interfaz junta esto con el histórico que ya tiene cargado y reemplaza los meses desde interfaz_desde_mes.
const cfg = $('Config').first().json;
const budget = $('Sheets: Budget para interfaz').first().json.valueRanges || [];
const control = $('Sheets: control para interfaz').first().json.valueRanges || [];
const desde = cfg.interfaz_desde_mes;
const mes = v => { const m = String(v ?? '').match(/^(\d{1,2})_/); return m ? +m[1] : 0; };
const vacia = f => !f.some((v, i) => i > 0 && v !== '' && v !== null && v !== undefined && v !== false);

function tablaBudget(valores) {
  const filas = valores || [];
  const h = filas.findIndex(f => String(f[0] ?? '').trim().toUpperCase() === 'VINTAGE');
  if (h < 0) return { enc: [], filas: [] };
  return { enc: filas[h], filas: filas.slice(h + 1).filter(f => mes(f[0]) >= desde && !vacia(f)) };
}
function tablaControl(valores, max) {
  const [enc = [], ...filas] = valores || [];
  const llenas = filas.filter(f => f.some(v => v !== '' && v !== null && v !== undefined));
  return { enc, filas: max ? llenas.slice(-max) : llenas };
}
const D = cfg.destinos;
// Si la lectura falló (por ejemplo un 503 de Google) no se sube nada: mejor datos de ayer que un archivo vacío.
const opex = tablaBudget(budget[0] && budget[0].values);
if (!budget.length || !opex.enc.length || !control.length) {
  return [{ json: { omitir: true, motivo: 'No se pudo leer el Budget o la hoja de control; la interfaz conserva los datos anteriores' } }];
}
const datos = {
  version: 1,
  generado: new Date().toISOString(),
  corrida: $('Estado').first().json.corrida,
  modo_prueba: cfg.modo_prueba,
  desde_mes: desde,
  fx: (budget[4] && budget[4].values) || [],
  tabs: {
    [D.OPEX]: opex,
    [D.FIXED_ASSETS]: tablaBudget(budget[1] && budget[1].values),
    [D.FINANCIAL]: tablaBudget(budget[2] && budget[2].values),
    [D.INCOME]: tablaBudget(budget[3] && budget[3].values)
  },
  control: {
    FACTURAS: tablaControl(control[0] && control[0].values),
    BITACORA: tablaControl(control[1] && control[1].values, 3000),
    N8N_CORRIDAS: tablaControl(control[2] && control[2].values, 60)
  }
};
return [{ json: { datos, resumen: Object.fromEntries(Object.entries(datos.tabs).map(([k, t]) => [k, t.filas.length])),
  facturas: datos.control.FACTURAS.filas.length } }];

// Avisos de la corrida: lo que falló sin detener el flujo (los nodos siguen aunque fallen para no perder el resto).
// Se mandan a Álvaro por mensaje directo de Slack y por correo. Si todo salió bien no se manda nada.
const cfg = $('Config').first().json;
const est = $('Estado').first().json;
const corrio = n => { try { return $(n).isExecuted; } catch (e) { return false; } };
const items = n => (corrio(n) ? $(n).all().map(i => i.json || {}) : []);
const errorDe = j => {
  if (!j || !j.error) return '';
  if (typeof j.error === 'string') return j.error;
  return String(j.error.description || j.error.message || JSON.stringify(j.error));
};
const avisos = [];

// 1. Claude: facturas y movimientos bancarios
for (const [nodo, que] of [['Claude', 'leer facturas'], ['Claude bancos', 'clasificar movimientos del banco']]) {
  const todos = items(nodo), errores = todos.map(errorDe).filter(Boolean);
  if (!errores.length) continue;
  const sinSaldo = errores.some(e => /credit balance/i.test(e));
  avisos.push(`*Claude (${que})*: fallaron ${errores.length} de ${todos.length} llamadas. ` +
    (sinSaldo ? 'No hay saldo en la cuenta de Anthropic: recarga en console.anthropic.com → Plans & Billing. Las facturas afectadas quedaron "por validar".'
      : `Error: ${errores[0].slice(0, 200)}`));
}

// 2. Slack: lectura del canal
const hist = items('Slack: historial del canal')[0];
if (cfg.slack_revisar_canal && hist && hist.ok === false) {
  avisos.push(`*Slack*: no se pudo leer el canal (${hist.error}${hist.needed ? `, falta el permiso ${hist.needed}` : ''}). ` +
    'Sin esto n8n no revisa si alguien ya pidió una factura. Agrega el permiso a la app y dale "Reinstall to Atrato".');
} else if (hist && errorDe(hist)) avisos.push(`*Slack*: no se pudo leer el canal: ${errorDe(hist).slice(0, 200)}`);

// 3. SAT, Metabase y XML del SAT
const planOut = corrio('Plan') ? $('Plan').first().json : {};
const meta = planOut.meta || {};
if (meta.sat_error) avisos.push(`*SAT (Todo Conta)*: ${meta.sat_error}`);
if (meta.bancos_error) avisos.push(`*Bancos (Metabase)*: ${meta.bancos_error}`);
const zip = [...items('SAT: descargar ZIP'), ...items('SAT: descomprimir')].map(errorDe).filter(Boolean);
if (zip.length) avisos.push(`*XML del SAT*: no se pudo bajar o abrir el ZIP (${zip[0].slice(0, 150)}). Las facturas sin PDF se quedan sin liga hasta la siguiente corrida.`);

// 4. Budget, Drive y Slack de esta corrida
const copiar = items('Sheets: copiar formato')[0];
if (copiar && errorDe(copiar)) {
  avisos.push(`*Budget*: no se copió el formato de los renglones nuevos (${errorDe(copiar).slice(0, 150)}). ` +
    (/filtered out row/i.test(errorDe(copiar)) ? 'Hay un filtro activo en OPEX: quítalo. Los datos sí se guardaron.' : 'Los datos sí se guardaron.'));
}
const esc = corrio('Escrituras') ? ($('Escrituras').first().json.totales || {}) : {};
if (esc.erroresDrive) avisos.push(`*Drive*: ${esc.erroresDrive} archivos no se pudieron subir. Sus facturas quedaron sin liga en Invoice.`);
if ((esc.bloqueados || []).length) avisos.push(`*Budget (candado)*: se bloquearon ${esc.bloqueados.length} cambios a celdas que ya tenían datos de una persona (${esc.bloqueados.slice(0, 5).join(', ')}${esc.bloqueados.length > 5 ? '…' : ''}). No se modificaron.`);
if (esc.erroresSlack) avisos.push(`*Slack*: ${esc.erroresSlack} mensajes de facturas pendientes no se pudieron publicar.`);
const resumenPrueba = items('Slack: resumen prueba')[0];
if (resumenPrueba && resumenPrueba.ok === false) avisos.push(`*Slack*: no se publicó el resumen de prueba (${resumenPrueba.error || errorDe(resumenPrueba)}).`);

// 5. Interfaz (artefacto)
const datosInterfaz = items('Datos interfaz')[0];
if (datosInterfaz && datosInterfaz.omitir) avisos.push(`*Interfaz*: ${datosInterfaz.motivo}`);
else if (datosInterfaz && errorDe(datosInterfaz)) avisos.push(`*Interfaz*: no se armaron los datos (${errorDe(datosInterfaz).slice(0, 150)}).`);
const subida = items('Drive: actualizar interfaz')[0];
if (subida && errorDe(subida)) avisos.push(`*Interfaz*: no se actualizó interfaz_gastos.json en Drive (${errorDe(subida).slice(0, 150)}). El artefacto muestra los datos de la corrida anterior.`);

if (!avisos.length) return [{ json: { ninguno: true } }];
const url = `https://alvarohv1998.app.n8n.cloud/workflow/${$workflow.id}/executions/${$execution.id}`;
const titulo = `:warning: *Avisos del flujo de gastos · corrida ${est.corrida}${cfg.modo_prueba ? ' (modo prueba)' : ''}*`;
const texto = [titulo, 'La corrida terminó, pero esto no salió bien:', ...avisos.map(a => `• ${a}`), `<${url}|Ver la ejecución en n8n>`].join('\n');
const h = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\*([^*]+)\*/g, '<b>$1</b>');
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#333">
<p><b>Avisos del flujo de gastos · corrida ${h(est.corrida)}</b></p><p>La corrida terminó, pero esto no salió bien:</p>
<ul>${avisos.map(a => `<li style="margin-bottom:6px">${h(a)}</li>`).join('')}</ul>
<p><a href="${url}">Ver la ejecución en n8n</a></p></div>`;
return [{ json: { cuerpo: { channel: cfg.avisos_slack, text: texto }, para: cfg.avisos_correo, asunto: `Avisos del flujo de gastos · corrida ${est.corrida}`, html, avisos } }];
